namespace ghidra.app.plugin.core.analysis;





using docking;
using docking.action;
using docking.widgets;
using ghidra;
using ghidra.framework.options;
using ghidra.program.model.listing;
using ghidra.util;
using ghidra.util;

/**
 * Dialog to show the panel for the auto analysis options.
 *
 */
public class AnalysisOptionsDialog : DialogComponentProvider, PropertyChangeListener {
	private bool doAnalysis;
	private AnalysisPanel panel;
	private EditorStateFactory editorStateFactory = new EditorStateFactory();
	private bool hasChanges;

	/**
	 * Constructor
	 * 
	 * @param program the program to run analysis on
	 */
	AnalysisOptionsDialog(Program program) : this(List.of(program))
    {
	}

	/**
	 * Constructor 
	 * 
	 * @param programs the set of programs to run analysis on
	 */
	AnalysisOptionsDialog(List<Program> programs) : base("Analysis Options")
    {
		setHelpLocation(new HelpLocation("AutoAnalysisPlugin", "AnalysisOptions"));
		panel = new AnalysisPanel(programs, editorStateFactory, this);
		panel.setToLastUsedAnalysisOptionsIfProgramNotAnalyzed();
		panel.getAccessibleContext().setAccessibleName("Analysis Options");
		addWorkPanel(panel);
		addOKButton();
		addCancelButton();
		addApplyButton();

		setOkButtonText("Analyze");
		okButton.setMnemonic('N'); // 'N' to avoid conflict with the 'A' in Apply

		setPreferredSize(1000, 600);
		setRememberSize(true);
		setHasChanges(panel.hasChangedValues());

		setFocusComponent(panel.getFocusComponent());

		List<DockingAction> actions = panel.getActions();
		foreach (DockingAction action in actions) {
			addAction(action);
		}
	}

	/* @Override */
	public void okCallback() {
		try {
			panel.applyChanges();
			doAnalysis = true;
			close();
		}
		catch (Exception e) {
			Msg.showError(this, panel, "Error Setting Analysis Options", e.getMessage(), e);
		}
	}

	/* @Override */
	protected void cancelCallback() {
		if (hasChanges) {
			int result = OptionDialog.showYesNoCancelDialog(panel, "Save Changes?",
				"These options are different from what is in the program.\n" +
					"Do you want to save them to the program?");
			if (result == OptionDialog.CANCEL_OPTION) {
				return;
			}
			if (result == OptionDialog.YES_OPTION) {
				panel.applyChanges();
			}
		}
		close();
	}

	/* @Override */
	protected void applyCallback() {
		panel.applyChanges();
		setHasChanges(false);
	}

	bool wasAnalyzeButtonSelected() {
		return doAnalysis;
	}

	private void setHasChanges(bool hasChanges) {
		this.hasChanges = hasChanges;
		setApplyEnabled(hasChanges);
	}

	/* @Override */
	public void propertyChange(PropertyChangeEvent evt) {
		if (evt.getPropertyName().equals(GhidraOptions.APPLY_ENABLED)) {
			setHasChanges((Boolean) evt.getNewValue());
		}
	}
}
